        { term: `Hydrograph`, def: `A graph showing river discharge over time.` },
        { term: `Choropleth map`, def: `A map shaded to show values in different areas.` },
        { term: `Mass tourism`, def: `Large-scale tourism, such as cruise-ship arrivals, involving many visitors.` },
        { term: `Ecotourism`, def: `Responsible travel to natural areas that conserves the environment and benefits local people.` },
        { term: `Sustainability`, def: `Meeting present needs without compromising those of the future.` }
