        { term: `Civil law system`, def: `A legal system based on codified laws, as in the Netherlands, Suriname, Haiti and the Dutch Caribbean.` },
        { term: `Precedent`, def: `A previous judicial decision that guides later cases.` },
        { term: `Stare decisis`, def: `The principle that courts follow earlier decisions on the same point of law.` },
        { term: `Ratio decidendi`, def: `The legal reason for a decision, which is binding on lower courts.` },
        { term: `Obiter dictum`, def: `A remark in a judgment that is not essential to the decision and is only persuasive.` },
        { term: `Plaintiff`, def: `The party who brings a civil action; also called the claimant.` },
        { term: `Defendant`, def: `The party against whom an action is brought.` },
        { term: `Tort`, def: `A civil wrong, other than breach of contract, for which damages may be claimed.` },
        { term: `Negligence`, def: `Failure to take reasonable care, causing damage to someone owed a duty of care.` },
        { term: `Duty of care`, def: `A legal obligation to avoid acts or omissions that could foreseeably harm others.` },
        { term: `Contract`, def: `A legally binding agreement between parties.` },
        { term: `Consideration`, def: `Something of value exchanged between parties to a contract.` },
        { term: `Burden of proof`, def: `The obligation to prove a claim or allegation.` },
        { term: `Beyond reasonable doubt`, def: `The standard of proof in criminal cases.` },
        { term: `Balance of probabilities`, def: `The standard of proof in civil cases.` },
        { term: `Jurisdiction`, def: `The authority of a court to hear and decide a case.` },
        { term: `Caribbean Court of Justice`, def: `The regional court serving as a final court of appeal for some CARICOM states and interpreting the Revised Treaty of Chaguaramas.` },
        { term: `Constitution`, def: `The fundamental law setting out the structure of government and citizens' rights.` }
